using System.Collections.Generic;
using UnityEngine;

namespace ExpoConvergence
{
    /// <summary>
    /// Material library. Templates live in Resources/ExpoMaterials (generated by Expo/Setup Project) so their
    /// shader variants ship in builds; tinted variants are cloned from them and cached.
    /// </summary>
    public static class ExpoMaterials
    {
        static readonly Dictionary<string, Material> Cache = new Dictionary<string, Material>();
        static readonly int BaseColor = Shader.PropertyToID("_BaseColor");
        static readonly int EmissionColor = Shader.PropertyToID("_EmissionColor");
        static readonly int Smoothness = Shader.PropertyToID("_Smoothness");
        static readonly int Metallic = Shader.PropertyToID("_Metallic");
        static readonly int ColorId = Shader.PropertyToID("_Color");
        static readonly int AlphaId = Shader.PropertyToID("_Alpha");

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        static void ResetCache() => Cache.Clear();

        /// <summary>Loads a named material from Resources/ExpoMaterials, or builds a fallback.</summary>
        public static Material Get(string name)
        {
            if (Cache.TryGetValue(name, out var m) && m != null) return m;
            m = Resources.Load<Material>("ExpoMaterials/" + name);
            if (m == null) m = BuildFallback(name);
            Cache[name] = m;
            return m;
        }

        static Material BuildFallback(string name)
        {
            Shader shader;
            if (name.StartsWith("M_Holo")) shader = Shader.Find("Expo/Hologram");
            else if (name.StartsWith("M_Field")) shader = Shader.Find("Expo/EnergyField");
            else if (name.StartsWith("M_Cone")) shader = Shader.Find("Expo/VisionCone");
            else if (name.StartsWith("M_Beam")) shader = Shader.Find("Expo/Beam");
            else if (name.StartsWith("M_Sky")) shader = Shader.Find("Expo/NightSky");
            else if (name.StartsWith("M_Particle")) shader = Shader.Find("Expo/ParticleAdd");
            else if (name.StartsWith("M_Glass")) shader = Shader.Find("Expo/Hologram");
            else shader = Shader.Find("Universal Render Pipeline/Lit");
            if (shader == null) shader = Shader.Find("Universal Render Pipeline/Unlit");
            var m = new Material(shader) { name = name + " (fallback)", enableInstancing = true };
            if (name.StartsWith("M_Emissive"))
            {
                m.EnableKeyword("_EMISSION");
                m.SetColor(BaseColor, Color.black);
                m.globalIlluminationFlags = MaterialGlobalIlluminationFlags.None;
            }
            return m;
        }

        static string Key(string prefix, Color c, float a = 0f, float b = 0f) =>
            $"{prefix}_{c.r:F3}_{c.g:F3}_{c.b:F3}_{c.a:F2}_{a:F2}_{b:F2}";

        /// <summary>Opaque URP Lit surface.</summary>
        public static Material Lit(Color color, float smoothness = 0.5f, float metallic = 0f)
        {
            string key = Key("lit", color, smoothness, metallic);
            if (Cache.TryGetValue(key, out var m) && m != null) return m;
            m = new Material(Get("M_LitBase")) { name = key };
            m.SetColor(BaseColor, color);
            m.SetFloat(Smoothness, smoothness);
            m.SetFloat(Metallic, metallic);
            Cache[key] = m;
            return m;
        }

        /// <summary>Glowing surface: black base with HDR emission (drives bloom).</summary>
        public static Material Emissive(Color color, float intensity = 3f, Color? baseColor = null)
        {
            string key = Key("em", color, intensity);
            if (baseColor.HasValue) key += "_b" + baseColor.Value.GetHashCode();
            if (Cache.TryGetValue(key, out var m) && m != null) return m;
            m = new Material(Get("M_EmissiveBase")) { name = key };
            m.SetColor(BaseColor, baseColor ?? new Color(0.02f, 0.02f, 0.03f));
            m.SetColor(EmissionColor, ExpoPalette.Hdr(color, intensity));
            m.EnableKeyword("_EMISSION");
            Cache[key] = m;
            return m;
        }

        /// <summary>A fresh (uncached) emissive material whose emission can be animated per object.</summary>
        public static Material EmissiveInstance(Color color, float intensity = 3f)
        {
            var m = new Material(Get("M_EmissiveBase")) { name = "em_instance" };
            m.SetColor(BaseColor, new Color(0.02f, 0.02f, 0.03f));
            m.SetColor(EmissionColor, ExpoPalette.Hdr(color, intensity));
            m.EnableKeyword("_EMISSION");
            return m;
        }

        public static void SetEmission(Material m, Color color, float intensity)
        {
            if (m != null) m.SetColor(EmissionColor, ExpoPalette.Hdr(color, intensity));
        }

        public static Material Holo(Color color, float alpha = 0.6f, bool instance = false)
        {
            string key = Key("holo", color, alpha);
            if (!instance && Cache.TryGetValue(key, out var m) && m != null) return m;
            m = new Material(Get("M_HoloBase")) { name = key };
            m.SetColor(ColorId, ExpoPalette.Hdr(color, 1.6f));
            m.SetFloat(AlphaId, alpha);
            if (!instance) Cache[key] = m;
            return m;
        }

        public static Material Field(Color color, float alpha = 0.55f, bool instance = false)
        {
            string key = Key("field", color, alpha);
            if (!instance && Cache.TryGetValue(key, out var m) && m != null) return m;
            m = new Material(Get("M_FieldBase")) { name = key };
            m.SetColor(ColorId, ExpoPalette.Hdr(color, 1.8f));
            m.SetFloat(AlphaId, alpha);
            if (!instance) Cache[key] = m;
            return m;
        }

        public static Material Cone(Color color, float alpha = 0.2f)
        {
            // Cones change colour per device state, so each one gets its own instance.
            var m = new Material(Get("M_ConeBase")) { name = "cone_instance" };
            m.SetColor(ColorId, ExpoPalette.Hdr(color, 1.4f));
            m.SetFloat(AlphaId, alpha);
            return m;
        }

        public static Material Beam(Color color, float intensity = 3f, bool instance = false)
        {
            string key = Key("beam", color, intensity);
            if (!instance && Cache.TryGetValue(key, out var m) && m != null) return m;
            m = new Material(Get("M_BeamBase")) { name = key };
            m.SetColor(ColorId, ExpoPalette.Hdr(color, intensity));
            if (!instance) Cache[key] = m;
            return m;
        }

        public static Material ParticleAdditive => Get("M_ParticleAdd");
        public static Material Sky => Get("M_Sky");
    }
}
